import numpy as np
from PIL import Image
m=np.array(Image.open('/app/target.png').convert('L'))<80
s=m.copy()
def shift(a,dy,dx): return np.roll(np.roll(a,dy,0),dx,1)
for it in range(100):
 change=False
 for ph in range(2):
  p=[shift(s,-1,0),shift(s,-1,1),shift(s,0,1),shift(s,1,1),shift(s,1,0),shift(s,1,-1),shift(s,0,-1),shift(s,-1,-1)]
  B=sum(x.astype('uint8') for x in p); A=sum((~p[k]&p[(k+1)%8]).astype('uint8') for k in range(8)); c=s&(B>=2)&(B<=6)&(A==1)
  if ph==0:c &= ~(p[0]&p[2]&p[4])&~(p[2]&p[4]&p[6])
  else:c &= ~(p[0]&p[2]&p[6])&~(p[0]&p[4]&p[6])
  if c.any():s[c]=0;change=True
 if not change:break
cnt=sum(shift(s,dy,dx) for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx)
for kind,mask in [('end',cnt==1),('branch',cnt>=3)]:
 ys,xs=np.where(mask)
 print(kind,len(xs),list(zip(xs.tolist(),ys.tolist()))[:200])
